export interface Ball {
  x: number
  y: number
  vx: number
  vy: number
  r: number
}

const GRAVITY = 0.2

export function simulate(balls: Ball[], width: number, height: number) {
  for (let b of balls) {
    b.vy += GRAVITY

    b.x += b.vx
    b.y += b.vy

    if (b.x - b.r < 0) {
      b.x = b.r
      b.vx = Math.abs(b.vx)
    }
    if (b.x + b.r > width) {
      b.x = width - b.r
      b.vx = -Math.abs(b.vx)
    }
    if (b.y - b.r < 0) {
      b.y = b.r
      b.vy = Math.abs(b.vy)
    }
    if (b.y + b.r > height) {
      b.y = height - b.r
      b.vy = -Math.abs(b.vy)
    }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const b1 = balls[i]
      const b2 = balls[j]
      const dx = b2.x - b1.x
      const dy = b2.y - b1.y
      const dist = Math.sqrt(dx * dx + dy * dy)
      const minDist = b1.r + b2.r

      if (dist < minDist) {
        const temp = b1.vx
        b1.vx = b2.vx
        b2.vx = temp

        const temp2 = b1.vy
        b1.vy = b2.vy
        b2.vy = temp2

        const overlap = (minDist - dist) / 2 + 0.1
        const ux = dx / dist
        const uy = dy / dist
        b1.x -= ux * overlap
        b1.y -= uy * overlap
        b2.x += ux * overlap
        b2.y += uy * overlap
      }
    }
  }
}

export function draw(
  canvas: HTMLCanvasElement,
  balls: Ball[],
  width: number,
  height: number
) {
  const ctx = canvas.getContext("2d")!
  ctx.fillStyle = "#fff"
  ctx.fillRect(0, 0, width, height)

  ctx.fillStyle = "#3b82f6"
  for (let b of balls) {
    ctx.beginPath()
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
    ctx.fill()
  }
}

