const colors = [
  "#e11d48",
  "#f97316",
  "#eab308",
  "#22c55e",
  "#06b6d4",
  "#3b82f6",
  "#8b5cf6",
  "#ec4899"
];

export function getTravelerColor(name: string): string {
  const code = name.charCodeAt(0) + name.charCodeAt(name.length - 1);
  return colors[code % colors.length];
}

